INSERT INTO `news` (`id`, `title`, `summary`, `category`, `source_name`, `source_url`, `published_at`, `created_at`) SELECT 122, 'Rumor: GTA VI online mode coming in 2027, Twitch CEO says', 'Rumor: Twitch chief executive Dan Clancy said GTA VI online will launch ''next year'' (2027), based on his team''s conversations with Rockstar. Rockstar has not announced an online mode, a date, a name or any details — GTA VI launched single-player only. GamesBeat also reported in October 2026 that a PC release is planned for the first quarter of 2027, citing unnamed sources; Rockstar did not comment. Treat both as unconfirmed until Rockstar announces them.', 'Rumor', 'gamesbeat.com', 'https://gamesbeat.com/grand-theft-auto-vis-pc-release-is-slated-for-q1-2027/', '2026-11-25', 1795596209452 WHERE NOT EXISTS (SELECT 1 FROM `news` WHERE `id` = 122 OR `title` = 'Rumor: GTA VI online mode coming in 2027, Twitch CEO says');
--> statement-breakpoint
INSERT INTO `news` (`id`, `title`, `summary`, `category`, `source_name`, `source_url`, `published_at`, `created_at`) SELECT 123, 'No GTA VI on PC yet — and the fake PC download sites are scams', 'Grand Theft Auto VI launched November 19, 2026 on PlayStation 5 and Xbox Series X|S only. Rockstar has not announced a PC version or a PC release date. Any site offering a GTA VI PC download or a browser version is fake — do not download anything from them. The fan recompilation project Leonida went offline on November 23-24 without a playable version. Take-Two has said its hit games usually reach all platforms over time, but no PC date exists.', 'Official', 'portedgames.com', 'https://portedgames.com/gta-6-pc/', '2026-11-25', 1795596209512 WHERE NOT EXISTS (SELECT 1 FROM `news` WHERE `id` = 123 OR `title` = 'No GTA VI on PC yet — and the fake PC download sites are scams');
--> statement-breakpoint
INSERT INTO `news` (`id`, `title`, `summary`, `category`, `source_name`, `source_url`, `published_at`, `created_at`) SELECT 124, 'GTA VI launch draws a record 7.9 million concurrent stream viewers', 'Grand Theft Auto VI''s launch drew a peak of 7,915,475 concurrent viewers across Twitch, YouTube, Kick, SOOP and CHZZK, with 125.47 million hours watched in the first 24 hours (Streams Charts, November 19, 2026) — more than four times the previous record for a game launch. Twitch alone peaked at about 3.31 million, the most for any single game in Twitch history.', 'Community', 'axis-intelligence.com', 'https://axis-intelligence.com/gta-6-statistics/', '2026-11-25', 1795596209532 WHERE NOT EXISTS (SELECT 1 FROM `news` WHERE `id` = 124 OR `title` = 'GTA VI launch draws a record 7.9 million concurrent stream viewers');
--> statement-breakpoint
INSERT INTO `news` (`id`, `title`, `summary`, `category`, `source_name`, `source_url`, `published_at`, `created_at`) SELECT 125, 'GTA VI leads The Game Awards 2026 with eight nominations, including Game of the Year', 'Grand Theft Auto VI leads The Game Awards 2026 with eight nominations, announced November 17, 2026: Game of the Year, Best Game Direction, Best Narrative, Best Art Direction, Best Audio Design, Best Score & Music, Best Action/Adventure, and Best Performance for Manni L. Perez as Lucia Caminos. The ceremony is December 10, 2026 at the Peacock Theater in Los Angeles, and public voting runs until December 9. GTA VI also won Most Anticipated Game at the show in each of the past two years.', 'Official', 'rockstarintel.com', 'https://rockstarintel.com/gta-vi-nominated-for-game-of-the-year-leads-nominations/', '2026-11-25', 1795596209555 WHERE NOT EXISTS (SELECT 1 FROM `news` WHERE `id` = 125 OR `title` = 'GTA VI leads The Game Awards 2026 with eight nominations, including Game of the Year');
